-- DP-007 Session Synchronization: a Session generated by a Recurring
-- Schedule that the organizer has since edited by hand keeps its own
-- values — sync excludes it. This flag is what "edited by hand" means:
-- set by UpdateSession whenever a PATCH touches a Template field on a
-- generated Session, never cleared. Sessions generated before this
-- migration start at false; any hand edits made to them earlier are not
-- recoverable (updated_at is also bumped by status transitions, so it
-- can't stand in for this).
ALTER TABLE sessions
  ADD COLUMN edited_after_generation BOOLEAN NOT NULL DEFAULT false;
